function setMotion(enabled){motionEnabled=enabled;document.body.classList.toggle('motion-paused',!enabled);$('#motion-toggle').setAttribute('aria-pressed',String(enabled));$('#motion-toggle').textContent=enabled?'Motion on':'Motion off';if(typeof spriteActor!=='undefined')restoreSprite();if(!enabled){scene.style.setProperty('--look-x','0px');scene.style.setProperty('--look-y','0px');}}
