reducedMotion.addEventListener('change',e=>setMotion(!e.matches));
function syncCharacter(next){
 const states={request:['listening','I’m listening. Let’s make a plan.','Reading your request…'],diff:['thinking','Your turn. Review the plan, then approve.','Proposed changes ready for your review.'],tests:['working','Checking the example, one step at a time.','Checking sample inputs and results…'],review:['complete','Done together. Ready for your review.','Example complete. Your review comes next.']};
 const [state,text,log]=states[next];scene.dataset.state=state;if(typeof spriteActor!=='undefined')restoreSprite();$('#aria-message').textContent=text;$('#hero-log').textContent=log;
 $('#hero-task').textContent={code:'Fix the failing date-format tests.',finance:'Prepare a reproducible research brief.',logistics:'Prepare an inventory reorder draft.'}[activeTask];
 $('#approve-task').disabled=next!=='diff'||approvedTask;
 $('#approve-task').textContent=next==='review'?'Example complete ✓':approvedTask?'Approved ✓':'Approve & continue →';
 $('#decision-label').textContent=next==='diff'?'Your turn: review the proposed '+(activeTask==='code'?'change.':'method.'):next==='review'?'Completed together · illustrative result':next==='tests'?'Checking the sample result…':'Aria is planning this example.';
 if(next==='review')document.querySelector('[data-case="'+activeTask+'"]').classList.add('completed');
}
function renderScenario(){const data=scenarioContent[activeTask];$('#editor-title').textContent='aria / '+activeTask+' / '+stage;message(data[stage]);$('#demo-status').textContent=stage==='diff'?'Proposed method · waiting for approval':stage==='review'?'Example complete · ready for human review':'Illustrative '+stage;$('.file-tree').style.opacity='.45';}
function chooseTask(task){stopPlayback();activeTask=task;approvedTask=false;$('#task-select').value=task;$('#demo-panel').classList.toggle('scenario-panel',task!=='code');$('.file-tree').style.opacity=task==='code'?'1':'.45';renderStage('request');}
$('#task-select').addEventListener('change',()=>chooseTask($('#task-select').value));
$('#try-task').addEventListener('click',()=>{const task=$('#try-task').dataset.task;$('#case-dialog').close();chooseTask(task);$('#demo').scrollIntoView();$('#tab-request').focus({preventScroll:true});});
$('#approve-task').addEventListener('click',()=>{if(stage!=='diff'||approvedTask)return;stopPlayback();approvedTask=true;renderStage('tests');timer=setInterval(()=>{renderStage('review');stopPlayback();},2200);});
function greet(){if(motionEnabled)setSprite(4);clearTimeout(greetTimeout);scene.classList.remove('greeting');void scene.offsetWidth;scene.classList.add('greeting');$('#aria-message').textContent='Hello! Pick a task. We’ll work through it together.';greetTimeout=setTimeout(()=>{scene.classList.remove('greeting');syncCharacter(stage);},2600);}
['#aria-orb','#aria-robot','#ip-actor'].forEach(id=>$(id).addEventListener('click',greet));
scene.addEventListener('pointermove',e=>{if(!motionEnabled||e.pointerType==='touch')return;cancelAnimationFrame(lookFrame);lookFrame=requestAnimationFrame(()=>{const box=scene.getBoundingClientRect();const x=(e.clientX-box.left)/box.width-.5,y=(e.clientY-box.top)/box.height-.5;scene.style.setProperty('--look-x',(x*3).toFixed(1)+'px');scene.style.setProperty('--look-y',(y*2).toFixed(1)+'px');});});
scene.addEventListener('pointerleave',()=>{cancelAnimationFrame(lookFrame);scene.style.setProperty('--look-x','0px');scene.style.setProperty('--look-y','0px');});
$('#approve-changes').addEventListener('click',()=>{if($('#approve-changes').dataset.approved==='true'){scene.dataset.state='complete';restoreSprite();$('#aria-message').textContent='Approved together. You make the final call.';}else syncCharacter(stage);});
const spriteActor=$('#ip-actor');
const poseRegistration=[[.116,.064],[.097,.065],[.045,.072],[.023,.064],[.120,-.015],[.099,-.011],[.049,-.011],[.029,-.012]];
let spriteRestoreTimer=null,spriteMoveFrame=null;
function setSprite(frame){if(!motionEnabled)frame=0;const [x,y]=poseRegistration[frame];spriteActor.dataset.frame=String(frame);spriteActor.style.setProperty('--sprite-x',(frame%4*100/3)+'%');spriteActor.style.setProperty('--sprite-y',(Math.floor(frame/4)*100)+'%');spriteActor.style.setProperty('--register-x',(-x*100)+'%');spriteActor.style.setProperty('--register-y',(-y*100)+'%');}
function restoreSprite(){clearTimeout(spriteRestoreTimer);setSprite(motionEnabled?({listening:0,thinking:5,working:6,complete:7}[scene.dataset.state]??0):0);spriteActor.style.setProperty('--actor-x','0px');spriteActor.style.setProperty('--actor-y','0px');}
$('.approval-visual').addEventListener('pointermove',e=>{if(!motionEnabled||e.pointerType==='touch'||scene.classList.contains('greeting'))return;cancelAnimationFrame(spriteMoveFrame);spriteMoveFrame=requestAnimationFrame(()=>{const b=spriteActor.getBoundingClientRect();const x=Math.max(-1,Math.min(1,(e.clientX-b.left-b.width/2)/100));const y=Math.max(-1,Math.min(1,(e.clientY-b.top-b.height/2)/100));setSprite(x<-.2?1:x>.2?2:0);spriteActor.style.setProperty('--actor-x',(x*3)+'px');spriteActor.style.setProperty('--actor-y',(y*2)+'px');});});
$('.approval-visual').addEventListener('pointerleave',()=>{cancelAnimationFrame(spriteMoveFrame);if(!scene.classList.contains('greeting'))restoreSprite();});
spriteActor.addEventListener('click',()=>{const identity=$('.approval-identity p');identity.textContent='Hello! Let’s try a task together.';setTimeout(()=>{identity.innerHTML='Plans. Makes changes.<br>You stay in control.';},2600);});
setInterval(()=>{if(!motionEnabled||document.hidden||scene.classList.contains('greeting')||spriteActor.matches(':hover'))return;setSprite(3);spriteRestoreTimer=setTimeout(restoreSprite,140);},7500);
